values ('281535d4-ebf5-427d-a0f1-d1030f415b66', '4efdcd38-f5e6-4f15-ac4f-76d8788c8053', 'loops-and-iteration', 'Loops and iteration', 'Repeat work over sequences and reason about when a loop should stop.', 'beginner', 40, 4, '["Iterate over a list with a for loop","Accumulate a result across iterations","Use range for a known number of repetitions","Avoid infinite while loops"]'::jsonb, '{"intro":"Loops repeat a block of code. A `for` loop visits items in a sequence. A `while` loop continues while a condition remains true.","sections":[{"title":"Accumulating","paragraphs":["A common pattern is to start with a neutral value and update it on each pass. For a sum, start at 0. For a product, start at 1. For a list of results, start with an empty list."],"code":"numbers = [3, 8, 2]\ntotal = 0\nfor number in numbers:\n    total += number\nprint(total)  # 13"},{"title":"while loops need progress","paragraphs":["A `while` loop must change something that affects its condition, or it may never stop. Add a clear update inside the loop and test the stopping case."],"code":"countdown = 3\nwhile countdown > 0:\n    print(countdown)\n    countdown -= 1\nprint(\"go\")"},{"title":"Filtering inside a loop","paragraphs":["Conditionals inside loops let you select or transform items. Keep the condition close to where the item is handled so the logic stays readable."],"code":"evens = []\nfor number in [1, 2, 3, 4, 5, 6]:\n    if number % 2 == 0:\n        evens.append(number)"}],"keyPoints":["for visits values; while repeats until a condition changes.","Initialize accumulators before the loop.","A while loop must make progress toward stopping.","The modulo operator % reveals divisibility."]}'::jsonb, true)
