values ('c2362d34-d7c7-4c8e-a92d-5625a91cfeb4', '4efdcd38-f5e6-4f15-ac4f-76d8788c8053', 'lists-and-collections', 'Lists and ordered collections', 'Index, slice, iterate, and transform ordered data while avoiding common mutation mistakes.', 'beginner', 35, 5, '["Access items by index and slice","Add and remove items safely","Build a new list from an existing one","Explain zero-based indexing and negative indexes"]'::jsonb, '{"intro":"A list is an ordered, mutable collection. Order matters, duplicates are allowed, and positions start at zero.","sections":[{"title":"Indexing and slicing","paragraphs":["`items[0]` is the first item. Negative indexes count from the end: `items[-1]` is the last item. A slice such as `items[1:3]` includes the start index but not the end index."],"code":"languages = [\"Python\", \"JavaScript\", \"Rust\"]\nprint(languages[0])    # Python\nprint(languages[-1])   # Rust\nprint(languages[0:2])  # [''Python'', ''JavaScript'']"},{"title":"Mutation vs a new list","paragraphs":["Methods like `append`, `remove`, and `sort` change the list in place. Methods like `sorted` return a new list. Decide whether callers should see the change."],"code":"scores = [72, 90, 61]\nordered = sorted(scores)\nprint(scores)   # [72, 90, 61]\nprint(ordered)  # [61, 72, 90]\nscores.sort(reverse=True)\nprint(scores)   # [90, 72, 61]"},{"title":"Iterating with context","paragraphs":["When you need both the position and the value, `enumerate` is clearer than manually tracking an index."],"code":"for index, language in enumerate([\"Python\", \"Rust\"]):\n    print(index, language)"}],"keyPoints":["Lists are ordered and mutable.","Indexes start at 0; negative indexes count from the end.","Slices exclude the end index.","Know whether a method mutates the list or returns a new one."]}'::jsonb, true)
