values ('67bf3a61-9afb-436c-a3c0-7759b3bba087', '4efdcd38-f5e6-4f15-ac4f-76d8788c8053', 'dictionaries-and-lookups', 'Dictionaries and lookups', 'Represent related facts as key-value pairs and count repeating values safely.', 'intermediate', 35, 6, '["Read and update dictionary entries","Avoid KeyError with get or membership checks","Count frequencies with a dictionary","Explain why keys must be unique"]'::jsonb, '{"intro":"A dictionary maps unique keys to values. It is the right tool when you need to look something up by name or identifier rather than by position.","sections":[{"title":"Reading and writing","paragraphs":["Use square brackets to read or write a key. Reading a missing key raises a KeyError. `get(key, default)` returns a default instead."],"code":"stock = {\"pens\": 12, \"paper\": 4}\nprint(stock[\"pens\"])            # 12\nprint(stock.get(\"ink\", 0))      # 0\nstock[\"ink\"] = 7\nstock[\"pens\"] += 1"},{"title":"Counting pattern","paragraphs":["A frequency table starts empty. For each item, read the current count with a default of 0, then write the incremented value back."],"code":"counts = {}\nfor word in [\"to\", \"be\", \"to\"]:\n    counts[word] = counts.get(word, 0) + 1\nprint(counts)  # {''to'': 2, ''be'': 1}"},{"title":"Iterating dictionaries","paragraphs":["Looping over a dictionary yields its keys. Use `.items()` when you need key-value pairs. Insertion order is preserved in modern Python."],"code":"scores = {\"Ada\": 95, \"Grace\": 91}\nfor name, score in scores.items():\n    print(f\"{name}: {score}\")"}],"keyPoints":["Keys are unique and must be hashable.","Use get() when a missing key is expected.","A dictionary is ideal for lookups and frequency counts.","Loop with .items() for keys and values together."]}'::jsonb, true)
