values ('0451353f-1753-41c9-ac89-6d4ba76e9d3d', '4efdcd38-f5e6-4f15-ac4f-76d8788c8053', 'modules-and-reuse', 'Modules and reusable code', 'Group related functions, separate execution from import, and expose a small public surface.', 'intermediate', 30, 10, '["Explain what happens when a module is imported","Use the if __name__ == \"__main__\" guard","Keep module-level constants meaningful","Design a small set of public helpers"]'::jsonb, '{"intro":"A module is a Python file that can be imported. Importing runs the file''s top-level code once, then makes its names available to the importer.","sections":[{"title":"Importing runs code","paragraphs":["Top-level statements execute on import. That is useful for defining constants and functions, but dangerous for side effects such as printing or reading command-line arguments. Put those behind a function and guard the call."],"code":"# pricing.py\nTAX_RATE = 0.2\n\ndef with_tax(price):\n    return round(price * (1 + TAX_RATE), 2)\n\nif __name__ == \"__main__\":\n    print(with_tax(10))"},{"title":"A small public surface","paragraphs":["Helpers that are only used inside a module can start with an underscore. `__all__` can document the names intended for importers, though it does not enforce privacy."],"code":"__all__ = [\"with_tax\", \"format_price\"]"},{"title":"Import styles","paragraphs":["`import pricing` keeps the module namespace. `from pricing import with_tax` imports one name. Prefer explicit imports when the origin of a name matters."],"code":"import pricing\nprint(pricing.with_tax(10))\n\nfrom pricing import with_tax\nprint(with_tax(20))"}],"keyPoints":["Importing a module executes its top-level code once.","Use if __name__ == \"__main__\" for script-only behavior.","Module constants should be meaningful and documented.","Prefer explicit imports when clarity matters."]}'::jsonb, true)
on conflict (id) do update set
  track_id = excluded.track_id,
  slug = excluded.slug,
  title = excluded.title,
  description = excluded.description,
  difficulty = excluded.difficulty,
  estimated_minutes = excluded.estimated_minutes,
  position = excluded.position,
  objectives = excluded.objectives,
  content = excluded.content,
  is_published = excluded.is_published;

insert into public.lessons (id, track_id, slug, title, description, difficulty, estimated_minutes, position, objectives, content, is_published)
values ('c89a7f16-a358-47a6-abdd-1066f272f934', '4efdcd38-f5e6-4f15-ac4f-76d8788c8053', 'classes-and-objects', 'Classes and objects', 'Model state and behavior with classes, constructors, methods, and clear invariants.', 'advanced', 50, 11, '["Define a class with __init__ and methods","Keep an invariant true across mutations","Distinguish instance state from class state","Use properties or methods to expose behavior"]'::jsonb, '{"intro":"A class is a blueprint for objects that share state and behavior. Use one when a group of values and the operations on them belong together, not merely to group unrelated functions.","sections":[{"title":"State and behavior","paragraphs":["`__init__` initializes a new instance. `self` refers to the instance being operated on. Methods can read and change instance attributes."],"code":"class Counter:\n    def __init__(self, start=0):\n        self.value = start\n\n    def increment(self, amount=1):\n        self.value += amount\n\ncounter = Counter()\ncounter.increment()\nprint(counter.value)  # 1"},{"title":"Protect invariants","paragraphs":["An invariant is something that should always be true, such as a bank balance never being negative after a withdrawal. Validation belongs in the method that could break it."],"code":"class Account:\n    def __init__(self, balance=0):\n        if balance < 0:\n            raise ValueError(\"balance cannot be negative\")\n        self.balance = balance\n\n    def withdraw(self, amount):\n        if amount > self.balance:\n            raise ValueError(\"insufficient funds\")\n        self.balance -= amount"}],"keyPoints":["Classes combine state with the behavior that protects it.","__init__ runs when an instance is created.","Validate in the method that could break an invariant.","Prefer the simplest tool; not everything needs a class."]}'::jsonb, true)
on conflict (id) do update set
  track_id = excluded.track_id,
  slug = excluded.slug,
  title = excluded.title,
  description = excluded.description,
  difficulty = excluded.difficulty,
  estimated_minutes = excluded.estimated_minutes,
  position = excluded.position,
  objectives = excluded.objectives,
  content = excluded.content,
  is_published = excluded.is_published;

insert into public.lessons (id, track_id, slug, title, description, difficulty, estimated_minutes, position, objectives, content, is_published)
values ('f043ae36-28e5-4c58-a3b0-24275eea8039', '4efdcd38-f5e6-4f15-ac4f-76d8788c8053', 'practical-project', 'Practical project: an expense report', 'Combine functions, collections, validation, and formatting into one small, testable report builder.', 'advanced', 55, 12, '["Translate a written specification into testable behavior","Validate records before aggregating them","Build a result from several small steps","Keep output separate from calculation"]'::jsonb, '{"intro":"This project combines the path so far. You will build a calculation function first, then a formatting function that depends on it. That separation makes each piece easier to test.","sections":[{"title":"Read the specification twice","paragraphs":["Before writing code, identify the inputs, the outputs, and the edge cases. Here each record is a dictionary with a category and an amount. The report needs a total, a per-category total, and a count."]},{"title":"Calculate, then format","paragraphs":["A calculation function should return data, not a paragraph of text. A formatter can then turn the data into a human-readable string. Keeping them separate means the formatter can change without breaking the math."]},{"title":"Test the edges","paragraphs":["What happens with an empty list? A zero amount? A negative amount? Decide deliberately, document the rule in the function, and test it."]}],"keyPoints":["Write behavior in small functions with clear contracts.","Validate input close to where it is used.","Calculations and presentation are separate responsibilities.","Test empty and boundary inputs."]}'::jsonb, true)
